using System.Collections.Generic;
using System.Linq;

public static class DocumentQueries
{
    public static List<DocumentRow> ListActive(IEnumerable<DocumentRow> rows, string? owner)
    {
        var query = rows.Where(row => !row.IsArchived);
        if (!string.IsNullOrWhiteSpace(owner))
        {
            query = query.Where(row => row.Owner == owner);
        }

        return query
            .OrderByDescending(row => row.UpdatedAt)
            .ToList();
    }
}

def list_active(rows, owner=None):
    filtered = [row for row in rows if not row["is_archived"]]
    if owner:
        filtered = [row for row in filtered if row["owner"] == owner]
    return sorted(filtered, key=lambda row: row["updated_at"], reverse=True)

