def list_workspace_listings(rows, workspace_id, category=None):
    filtered = [
        row for row in rows
        if row["workspace_id"] == workspace_id and row["status"] == "published"
    ]
    if category:
        filtered = [row for row in filtered if row["category"] == category]
    return sorted(filtered, key=lambda row: row["updated_at"], reverse=True)

def build_vendor_payout(transactions, vendor_id):
    rows = [
        row for row in transactions
        if row["vendor_id"] == vendor_id and row["status"] == "settled"
    ]
    gross = sum(row["amount"] for row in rows)
    fees = sum(row["platform_fee"] for row in rows)
    return {"gross": gross, "fees": fees, "net": gross - fees, "order_count": len(rows)}

def can_view_document(document, user):
    if document.get("archived"):
        return False
    if document.get("owner_id") == user.get("id"):
        return True
    if document.get("visibility") == "public":
        return True
    if document.get("visibility") == "team" and document.get("team_id") in user.get("team_ids", []):
        return True
    return user.get("id") in document.get("shared_with", [])

def latest_reviewable_version(versions):
    reviewable = [v for v in versions if v.get("status") in {"approved", "published"}]
    if not reviewable:
        return None
    return max(reviewable, key=lambda item: item.get("version_number", 0))

def has_booking_conflict(existing, candidate):
    for booking in existing:
        if booking.get("field_id") != candidate.get("field_id"):
            continue
        if candidate.get("start") < booking.get("end") and booking.get("start") < candidate.get("end"):
            return True
    return False

def quote_booking(base_price, start_hour, duration_hours, is_weekend):
    base_total = base_price * duration_hours
    total = base_total
    if is_weekend:
        total += base_total * 0.20
    if start_hour >= 18:
        total += base_total * 0.15
    return round(total, 2)

def executable_signals(signals, processed_ids):
    return [
        signal for signal in signals
        if signal.get("status") == "ready" and signal.get("signal_id") not in processed_ids
    ]

def can_open_position(account, order):
    if abs(account.get("daily_pnl", 0)) > account.get("max_daily_loss", 0):
        return False
    projected = account.get("current_exposure", 0) + order.get("notional", 0)
    return projected <= account.get("max_exposure", 0)

def next_agent_action(state):
    if not state.get("objective"):
        return "clarify"
    if not state.get("evidence"):
        return "retrieve"
    if state.get("needs_tool"):
        return "tool_call"
    return "answer"

def due_cards(cards, today):
    filtered = [
        card for card in cards
        if not card.get("suspended") and card.get("due_at", 0) <= today
    ]
    return sorted(filtered, key=lambda card: (card.get("due_at", 0), card.get("ease", 0)))

def can_install_listing(listing, workspace):
    if listing.get("status") != "published":
        return False
    if workspace.get("subscription_status") != "active":
        return False
    plan = workspace.get("plan")
    return plan == "enterprise" or plan in listing.get("allowed_plans", [])

def rank_featured_listings(rows, segment):
    filtered = [row for row in rows if row.get("segment") == segment and row.get("status") == "published"]
    return sorted(filtered, key=lambda row: (not row.get("featured", False), -row.get("rating", 0), -row.get("installs", 0), row.get("name", "")))

def review_queue(rows, reviewer_id):
    filtered = [row for row in rows if row.get("reviewer_id") == reviewer_id and row.get("status") == "pending" and not row.get("archived")]
    return sorted(filtered, key=lambda row: (row.get("due_at", 0), -row.get("version_number", 0)))

def retention_candidates(rows, today):
    filtered = [
        row for row in rows
        if row.get("retention_until", 0) <= today
        and not row.get("legal_hold")
        and row.get("status") in {"approved", "published"}
    ]
    filtered.sort(key=lambda row: row.get("retention_until", 0))
    return [row.get("document_id") for row in filtered]

