def can_reschedule_booking(booking, target_slot, existing):
    if booking.get("status") != "active" or booking.get("hours_until_start", 0) < 24:
        return False
    for row in existing:
        if row.get("id") == booking.get("id"):
            continue
        if row.get("field_id") != target_slot.get("field_id"):
            continue
        if target_slot.get("start") < row.get("end") and row.get("start") < target_slot.get("end"):
            return False
    return True

def refund_amount(booking):
    total = booking.get("total", 0)
    if booking.get("weather_closed") or booking.get("venue_cancelled"):
        return total
    hours = booking.get("hours_until_start", 0)
    if hours >= 48:
        return round(total * 0.8, 2)
    if hours >= 24:
        return round(total * 0.5, 2)
    return 0

def net_exposure_by_symbol(rows):
    summary = {}
    for row in rows:
        if row.get("status") != "open":
            continue
        sign = 1 if row.get("side") in {"long", "buy"} else -1
        symbol = row.get("symbol")
        summary[symbol] = summary.get(symbol, 0) + sign * row.get("quantity", 0)
    return summary

def triggered_stop_orders(orders, price):
    triggered = []
    for order in orders:
        if order.get("status") != "active":
            continue
        if order.get("side") == "sell" and price <= order.get("stop_price", 0):
            triggered.append(order.get("id"))
        if order.get("side") == "buy" and price >= order.get("stop_price", 0):
            triggered.append(order.get("id"))
    return triggered

def render_cited_answer(sections, evidence):
    index = {item.get("id"): position + 1 for position, item in enumerate(evidence)}
    rendered = []
    for section in sections:
        numbers = sorted({index[cid] for cid in section.get("cited_chunk_ids", []) if cid in index})
        markers = "".join(f"[{number}]" for number in numbers)
        rendered.append(f"{section.get('text', '')}{markers}")
    return rendered

def diversified_context(chunks, limit):
    chosen = []
    seen_docs = set()
    for chunk in chunks:
        document_id = chunk.get("document_id")
        if document_id in seen_docs:
            continue
        chosen.append(chunk)
        seen_docs.add(document_id)
        if len(chosen) == limit:
            break
    return chosen

def review_outcome(card, rating):
    interval = card.get("interval", 1)
    ease = card.get("ease", 2.5)
    if rating == "again":
        return {"next_interval": 1, "next_ease": round(max(1.3, ease - 0.2), 2)}
    if rating == "hard":
        return {"next_interval": max(2, int(interval * 1.2)), "next_ease": round(max(1.3, ease - 0.05), 2)}
    if rating == "easy":
        return {"next_interval": max(2, int(interval * ease * 1.3)), "next_ease": round(ease + 0.15, 2)}
    return {"next_interval": max(2, int(interval * ease)), "next_ease": round(ease, 2)}

def deck_overview(cards, deck_id, today):
    rows = [card for card in cards if card.get("deck_id") == deck_id]
    return {
        "total": len(rows),
        "new": sum(1 for card in rows if card.get("reps", 0) == 0),
        "due": sum(1 for card in rows if card.get("due_at", 0) <= today and not card.get("suspended")),
        "suspended": sum(1 for card in rows if card.get("suspended")),
    }
